<template>
 <a class="skip" href="#kg-main">跳至幼稚園選校內容</a>
 <header class="kg-header"><RouterLink to="/" class="kg-brand">香港選校年鑑 <small>幼稚園・家長版</small></RouterLink><nav aria-label="家長版主要導覽"><RouterLink to="/kindergarten">搵幼稚園</RouterLink><RouterLink to="/kindergarten/plan">我的報名清單</RouterLink><RouterLink to="/sources">來源及更新</RouterLink><RouterLink to="/schools?level=PRIMARY">小學</RouterLink><RouterLink to="/schools?level=SECONDARY">中學</RouterLink></nav></header>
 <main id="kg-main" class="kg-main">
  <p v-if="message" role="status" class="kg-success">{{ message }}</p><p v-if="error" role="alert" class="kg-caution">{{ error }} <button @click="load">重新載入</button></p>
  <section v-if="isList" class="kg-hero"><p class="kg-kicker">從你一家人的日常需要開始</p><h1>{{ route.path==='/'?'選校，從完整資料開始。':'先搵到夾你生活的幼稚園。' }}</h1><p>幾時報名、要畀幾多錢、接送時間夾唔夾？<br />把資料變成清楚答案，再用原文理解教學及支援。</p><p class="kg-small">先做好幼稚園；小學及中學仍可使用原有完整資料。沒有學校排名或錄取機會預測。</p></section>
  <section v-if="manifest" class="kg-needs" aria-labelledby="needs-title"><h2 id="needs-title">你的選校需要</h2><p>只用來整理畫面，不會傳送到模型。資料不足會列為待確認，不當作不符合。</p>
   <form @submit.prevent="apply" class="kg-form"><label>入學學年<select v-model.number="year"><option v-for="y in years" :key="y" :value="y">{{ y }}/{{ String(y+1).slice(-2) }}</option></select></label><label>年級<select v-model="grade"><option>K1</option><option>K2</option><option>K3</option></select></label><label>班別<select v-model="session"><option v-for="(s,k) in sessions" :key="k" :value="k">{{ s }}</option></select></label><label v-if="isList">地區<select v-model="district"><option value="">全部地區</option><option v-for="d in districts" :key="d">{{ d }}</option></select></label><label v-if="isList" class="kg-wide">校名或地址<input v-model="query" type="search" placeholder="例如：上水、惠州、青年會" maxlength="200" /></label><label>希望接走時間（選填）<input type="time" v-model="pickup" /></label><label>全年預算 HK$（選填）<input type="number" min="0" max="1000000" step="100" v-model.number="budget" placeholder="例如：30000" /></label><button>按需要更新</button></form>
  </section>
  <p v-if="loading">正在整理幼稚園資料…</p>
  <template v-if="manifest&&!loading">
   <template v-if="isList"><div class="kg-result-heading"><div><h2>可以開始了解的學校</h2><p>{{ matches.length }} 個校址資料組。以下按校名顯示，沒有按質素或模型信心排序。</p></div><button :disabled="selected.length<2" @click="compare">比較 {{ selected.length }} 間</button></div>
    <div class="kg-list"><article v-for="s in visible" :key="s.id" class="kg-search-card"><p class="kg-kicker">{{ s.district }}</p><h3><RouterLink :to="schoolURL(s.id)">{{ s.name }}</RouterLink></h3><p>{{ s.address }}</p><p>{{ sessionMeaning(s,session) }}</p><div class="kg-search-answer"><strong>費用</strong><span>{{ listCost(s) }}</span><small>{{ feePeriod(s.fee_effective_from,year) }}</small></div><div class="kg-search-answer"><strong>報名</strong><span>{{ s.has_school_events?'有本校招生公告可查，請核对適用學年':'先查目標學年校方公告' }}</span></div><p class="kg-small">{{ s.profile_available?'有年度教學及支援原文可了解。':'未接通本校址年度概覽，仍可查註冊及基本資料。' }}</p><div class="kg-card-actions"><label><input type="checkbox" :checked="selected.includes(s.id)" @change="toggle(s.id)" aria-label="加入家長比較" />加入比較</label><RouterLink :to="schoolURL(s.id)">了解這間學校 →</RouterLink></div></article></div>
    <p v-if="!matches.length" class="kg-caution">這個搜尋沒有結果，可改用部分校名或清除地區。沒有資料不代表學校不存在。</p><button v-if="visible.length<matches.length" class="light" @click="limit+=12">再顯示 12 間</button>
   </template>
   <template v-else-if="isPlan"><h1>我的幼稚園報名清單</h1><p>先列出要確認嘅事項，再記錄自己做咗邊一步。只存此瀏覽器，網站不會替你交表或提交兒童資料。</p><RouterLink to="/shortlist">匯出／匯入備份及原有私人清單 →</RouterLink><p v-if="!kgNotes.length">未有幼稚園收藏。先找到兩三間值得了解的學校，再加入清單。</p><article v-for="n in kgNotes" :key="n.id+':'+n.year" class="kg-answer"><h2><RouterLink :to="{path:'/kindergarten/'+n.id,query:{year:String(n.year)}}">{{ n.name }}</RouterLink></h2><p>{{ n.year }}/{{ String(n.year+1).slice(-2) }}</p><p>先确认：① 交表方法及截止日期　② 班別及接走時間　③ 學費、期數及其他支出。</p><label>我的進度<select v-model="n.status"><option value="considering">了解及查詢中</option><option value="preparing">準備報名資料</option><option value="applied">我已完成申請</option><option value="waiting">等候學校通知</option><option value="result_received">已收到結果</option></select></label><label>查詢回覆及私人筆記<textarea v-model="n.note" maxlength="4000" /></label><button :disabled="saving" @click="persist">儲存進度及筆記</button></article></template>
   <template v-else><RouterLink to="/kindergarten">← 繼續搵幼稚園</RouterLink><h1>{{ isCompare?'你選中的幼稚園：先看實際差異':'了解這間幼稚園' }}</h1><p>同一個需要、同一個年級及班別逐間看。舊價目與未有答案的項目，會清楚分開。</p>
    <section v-if="isCompare&&schools.length" class="kg-quick-compare"><h2>一眼看出要確認嘅差異</h2><div class="kg-scroll"><table><caption>已知小計不等於全年完整總成本；舊版費用不自動當成目標學年報價。</caption><thead><tr><th>你關心嘅事</th><th v-for="s in schools" :key="s.id">{{ s.name }}</th></tr></thead><tbody><tr><th>本版已知費用</th><td v-for="s in schools" :key="s.id"><strong>{{ detailCost(s) }}</strong><small>{{ feePeriod(s.fees.effective_from,year) }}</small></td></tr><tr><th>接送及班別</th><td v-for="s in schools" :key="s.id">{{ sessionMeaning(s,session) }}<small>{{ careMatch(s,session,pickup,year) }}</small></td></tr><tr><th>報名下一步</th><td v-for="s in schools" :key="s.id">{{ noteStatus(s,grade,year) }}</td></tr><tr><th>{{ topics[focus] }}</th><td v-for="s in schools" :key="s.id">{{ s.parent_analysis.selections[focus]?.state==='SUPPORTED'?short(s.parent_analysis.selections[focus]?.evidence?.text):'未有足夠清楚的已通過門檻原文，請向學校查詢。' }}</td></tr></tbody></table></div></section>
    <div class="kg-focus" role="group" aria-label="你最關心的安排"><button v-for="(label,key) in topics" :key="key" :class="{light:focus!==key}" :aria-pressed="focus===key" @click="focus=key">{{ label }}</button></div>
    <KGSchoolCard v-for="s in schools" :key="s.id" :school="s" :year="year" :grade="grade" :session="session" :pickup="pickup" :budget="budget||0" :focus="focus" @save="saveSchool" @questions="saveQuestions" />
    <section v-if="grade==='K1'&&commonEvents.length" class="kg-answer"><h2>另外留意：共同入學程序</h2><p>以下不是每間學校的報名日期，必須符合公告適用條件；不自動判定你或所選學校參與。</p><p v-for="e in commonEvents.filter(e=>e.entry_year===year)" :key="e.id"><strong>{{ e.title }}：{{ e.starts_on }}{{ e.ends_on?' 至 '+e.ends_on:'' }}</strong><br />{{ e.applicability }} <a :href="safeLink(e.source_url)??undefined" target="_blank" rel="noopener noreferrer">查看教育局公告</a></p></section>
   </template>
   <details class="kg-coverage"><summary>資料覆蓋、限制及完整來源</summary><p>保留原有 {{ manifest.source_groups }} 個幼稚園顯示組網址及 {{ manifest.annual_profiles }} 筆概覽，按既有校址證據整理成 {{ manifest.parent_cards }} 張卡片；不是經官方認證的獨立學校總數。</p><p>本輪只重整幼稚園。收費證明書按實際擷取及通過核對的範圍展示；個別學校當屆招生及時間表仍未全港齊備。並未進行真人家長使用測試或模型準確率校準。</p><p><RouterLink to="/sources">所有原始來源及版本</RouterLink> · <a href="/downloads/kg-parent-data.zip">下載幼稚園家長版資料與證據</a></p></details>
  </template>
 </main><footer class="kg-footer">家長作決定，資料幫你問對問題。<RouterLink to="/sources">查來源</RouterLink> · <RouterLink to="/about">私隱</RouterLink></footer>
</template>
<script setup lang="ts">
import {ref,computed,watch,onMounted} from 'vue';import {RouterLink,useRoute,useRouter} from 'vue-router';import {readJSON,safeLink,display,type Admission} from '../catalog';import {loadNotes,saveNotes,type PrivateState} from '../private';import KGSchoolCard from './KGSchoolCard.vue';import {costs,money,feePeriod,sessions,sessionMeaning,selectedIds,noteStatus,careMatch,topics,type KGManifest,type KGSummary,type KGSchool} from './model';import './style.css';
const route=useRoute(),router=useRouter();const manifest=ref<KGManifest|null>(null),index=ref<KGSummary[]>([]),schools=ref<KGSchool[]>([]),commonEvents=ref<Admission[]>([]);const loading=ref(true),error=ref(''),message=ref(''),saving=ref(false),privateReady=ref(false);const notes=ref<PrivateState>({revision:0,entries:[]});const year=ref(new Date().getFullYear()+1),grade=ref('K1'),session=ref('WD'),district=ref(''),query=ref(''),pickup=ref(''),budget=ref<number|undefined>(),focus=ref('learning'),limit=ref(12),selected=ref<string[]>([]);let generation=0;
const years=[2026,2027,2028,2029,2030];const isList=computed(()=>['/','/kindergarten'].includes(route.path)),isPlan=computed(()=>route.path==='/kindergarten/plan'),isCompare=computed(()=>route.path==='/kindergarten/compare');const districts=computed(()=>[...new Set(index.value.map(s=>s.district).filter(Boolean))].sort());const matches=computed(()=>index.value.filter(s=>(!district.value||s.district===district.value)&&(s.name+s.address).normalize('NFKC').includes(query.value.normalize('NFKC'))));const visible=computed(()=>matches.value.slice(0,limit.value));const kgNotes=computed(()=>{const ids=new Set(index.value.flatMap(s=>s.aliases));return notes.value.entries.filter(n=>ids.has(n.id));});
const short=(s?:string)=>s?display(s).slice(0,180)+(s.length>180?'…':''):'未有足夠清楚的原文。';const schoolURL=(id:string)=>({path:'/kindergarten/'+id,query:{year:String(year.value),grade:grade.value,session:session.value}});
function listCost(s:KGSummary){const c=costs(s.tuition_rows,grade.value,session.value);return c.subtotal===null?'尚未有可核對的小計':money(c.subtotal)+'／年，已知小計';}function detailCost(s:KGSchool){const c=costs(s.fees.rows,grade.value,session.value);return c.subtotal===null?'未有可計算資料':money(c.subtotal)+'／年';}
function toggle(id:string){if(selected.value.includes(id)){selected.value=selected.value.filter(x=>x!==id);return;}if(selected.value.length===4){error.value='最多比較四間幼稚園。';return;}selected.value.push(id);}
function compare(){void router.push({path:'/kindergarten/compare',query:{ids:selected.value.join(','),year:String(year.value),grade:grade.value,session:session.value}});}
function apply(){limit.value=12;const q={...route.query,year:String(year.value),grade:grade.value,session:session.value,q:query.value||undefined,district:district.value||undefined};void router.replace({path:route.path==='/'?'/kindergarten':route.path,query:q});}
async function load(){const gen=++generation;loading.value=true;error.value='';schools.value=[];try{const m=await readJSON<KGManifest>('/kg-parent-manifest.json');if(m.phase!=='KG_ONLY'||m.schema!==1||!/^[a-f0-9]{64}$/.test(m.bundle_id))throw new Error('幼稚園資料版本未通過核對。');const ix=await readJSON<KGSummary[]>('/kg-parent/'+m.bundle_id+'/index.json');if(ix.length!==m.parent_cards||new Set(ix.flatMap(s=>s.aliases)).size!==m.source_groups)throw new Error('幼稚園資料覆蓋不一致。');if(gen!==generation)return;manifest.value=m;index.value=ix;
 const y=Number(route.query.year);year.value=years.includes(y)?y:new Date().getFullYear()+1;grade.value=['K1','K2','K3'].includes(String(route.query.grade))?String(route.query.grade):'K1';session.value=Object.keys(sessions).includes(String(route.query.session))?String(route.query.session):'WD';district.value=String(route.query.district??'');query.value=String(route.query.q??'').slice(0,200);
 if(!isList.value&&!isPlan.value){const ids=isCompare.value?String(route.query.ids??'').split(',').filter(Boolean):[route.path.split('/')[2]];if(isCompare.value&&(ids.length<2||ids.length>4))throw new Error('請選兩至四間幼稚園。');if(ids.some(i=>!/^school_[a-f0-9]{24}$/.test(i)))throw new Error('幼稚園編號不正確。');const chosen=selectedIds(ids,ix);const rows=await Promise.all(chosen.map(s=>readJSON<KGSchool>('/kg-parent/'+m.bundle_id+'/schools/'+s.id+'.json')));if(rows.some((r,i)=>r.id!==chosen[i].id))throw new Error('學校資料不一致。');const events=await readJSON<Admission[]>('/kg-parent/'+m.bundle_id+'/common-events.json');if(gen===generation){schools.value=rows;commonEvents.value=events;}}}
 catch(e){if(gen===generation)error.value=String(e);}finally{if(gen===generation)loading.value=false;}}
async function persist(){if(!privateReady.value||saving.value)return;saving.value=true;message.value='';try{notes.value=await saveNotes(notes.value);message.value='已儲存於此瀏覽器。';}catch(e){error.value=String(e);}finally{saving.value=false;}}
async function saveSchool(s:KGSchool){if(!privateReady.value){error.value='私人儲存尚未準備好，請稍後重試。';return;}if(notes.value.entries.some(n=>s.aliases.includes(n.id)&&n.year===year.value)){message.value='已在你的私人清單。';return;}notes.value.entries.push({id:s.id,name:s.name,year:year.value,note:'',status:'considering'});await persist();}
async function saveQuestions(s:KGSchool){await saveSchool(s);const n=notes.value.entries.find(n=>s.aliases.includes(n.id)&&n.year===year.value);if(!n)return;const text=`\n待向學校確認（${year.value}/${String(year.value+1).slice(-2)} ${grade.value}）：\n1. 申請方法、文件及截止日期？\n2. ${sessions[session.value]}正常時間、最遲接走與延長照顧費？\n3. 全年學費期數、膳食、校車及用品費？\n4. ${s.parent_analysis.selections[focus.value]?.question??'新生適應及家長參與安排？'}`;if(n.note.length+text.length>4000){error.value='筆記超過上限，原文未截斷；請先整理筆記。';return;}n.note+=text;await persist();}
watch(()=>route.fullPath,()=>void load());onMounted(()=>{void load();void loadNotes().then(n=>{notes.value=n;privateReady.value=true;}).catch(e=>{error.value=String(e);});});
</script>
